function compute(s) {
  const raw = s.probs.slice();
  const n = raw.length;
  const sum = raw.reduce((a, b) => a + b, 0);
  const normalize = !!s.normalize;
  const validSum = Math.abs(sum - 1) < 1e-9;
  const canNormalize = sum > 0;
  const useNormalized = normalize && canNormalize;
  const p = useNormalized ? raw.map(v => v / sum) : raw.slice();
  const defined = useNormalized || validSum;

  const contributions = p.map(v => (v > 0 ? -v * Math.log2(v) : 0));
  const H = contributions.reduce((a, b) => a + b, 0);
  const support = p.filter(v => v > 0).length;
  const uniformH = support > 0 ? Math.log2(support) : 0;
  const maxP = p.length ? Math.max(...p) : 0;
  const minPositive = support ? Math.min(...p.filter(v => v > 0)) : 0;

  const metrics = [
    { label: "Entropy H", value: defined ? H : null, unit: "bits", defined: defined, reason: defined ? undefined : "probabilities do not sum to 1 and normalization is off" },
    { label: "Number of outcomes n", value: n, unit: "", defined: true },
    { label: "Sum of probabilities", value: sum, unit: "", defined: true },
    { label: "Uniform max log₂ n", value: uniformH, unit: "bits", defined: true },
    { label: "H as fraction of max", value: defined && uniformH > 0 ? H / uniformH : (defined ? 0 : null), unit: "", defined: defined, reason: defined ? undefined : "H undefined" }
  ];

  const steps = [
    { label: "Probability sum", formula: "Σ pᵢ", value: sum, explanation: useNormalized ? "Values were divided by this sum to normalize." : "Raw sum; must equal 1 for a valid distribution." },
    { label: "Largest probability", formula: "max pᵢ", value: maxP, explanation: "A single pᵢ = 1 forces H = 0 (certainty)." },
    { label: "Smallest positive pᵢ", formula: "min pᵢ > 0", value: minPositive, explanation: "Small positive probabilities contribute more per outcome." },
    { label: "Total entropy", formula: "H = -Σ pᵢ log₂ pᵢ", value: defined ? H : "undefined", explanation: defined ? "Sum of the per-outcome contributions." : "Cannot compute H without a valid distribution." }
  ];

  const labels = p.map((_, i) => "p" + (i + 1));
  const panels = [
    { kind: "bar", title: "Per-outcome contribution", description: "Each bar is -pᵢ log₂ pᵢ in bits; the total is H.", labels: labels, values: contributions, unit: "bits" },
    { kind: "table", title: "Probabilities and terms", description: "Editable probabilities, their contributions, and the running total.", columns: ["Outcome", "pᵢ", "-pᵢ log₂ pᵢ (bits)"], rows: p.map((v, i) => ["p" + (i + 1), v, contributions[i]]) },
    { kind: "line", title: "H vs n for uniform", description: "Maximum entropy log₂ n grows with the number of equally likely outcomes; your current H is marked by the bar chart.", xLabel: "n", yLabel: "log₂ n (bits)", series: [{ name: "uniform max", points: Array.from({ length: 8 }, (_, k) => [k + 1, Math.log2(k + 1)]) }] }
  ];

  let message;
  if (!defined) {
    message = "Probabilities sum to " + sum.toFixed(4) + ", not 1, and normalization is off. Turn normalization on or adjust values so H is defined.";
  } else if (H < 1e-12) {
    message = "H = 0 bits: one outcome is certain, so there is no uncertainty before observing it.";
  } else if (Math.abs(H - uniformH) < 1e-9) {
    message = "H = log₂ n = " + uniformH.toFixed(4) + " bits: the distribution is uniform over its " + support + " positive outcomes, the maximum for that support.";
  } else {
    message = "H = " + H.toFixed(4) + " bits, below the uniform maximum of " + uniformH.toFixed(4) + " bits for " + support + " positive outcomes.";
  }

  return { metrics: metrics, panels: panels, steps: steps, message: message };
}
